"""Give every portrait a persistent independent art brief; unspecified features are interpretive, never historical claims."""
import json,hashlib
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];out=ROOT/'outputs/harem-roster-draft';art_dir=out/'portraits'
data=json.loads((out/'roster-data.json').read_text())
faces=['a long oval face with gently prominent cheekbones','a softly rounded face with full cheeks','a broad face with a softly squared jaw','a tapered heart-shaped face with a broad forehead','an angular oval face with a firm chin','a compact rounded face with a small chin','an elongated face with a straight strong nose','a full face with deep-set thoughtful eyes','a slightly rectangular face with a defined jaw','an oval face with a gently convex nose']
