palettes=['muted indigo, ivory and subdued gold','deep madder red, warm cream and dark brown','soft sage green, ochre and ivory','dusty plum, warm gray and old gold','earth brown, faded coral and cream','dark blue-green, pale gold and unbleached linen','soft celadon, ink blue and ivory','muted saffron, deep burgundy and cream','dove gray, dull rose and tarnished silver','dark olive, russet and cream','smoky blue, rich brown and pale gold','warm white, subtle lavender and dark gray']
