base='Use case: historical-scene. Create ONE independent high-quality historical game full-body character illustration. A fully clothed adult woman, age 25 or older, standing calmly. Vertical 2:3 composition, whole head and both shoes within frame with margins. Realistic watercolor and graphite with lifelike anatomy and meticulous textile detail. Genuine transparent background, no backdrop, glow, lettering, frame or watermark. '
jobs=[]
for g in data['groups']:
 for p in g['people']:
  seed=hashlib.sha256(p['id'].encode()).digest();name=p['name'];hint=next((v for k,v in hints.items() if name==k or name.startswith(k+'（')),'')
  art={'face':faces[seed[0]%len(faces)],'eyes':eyes[seed[1]%len(eyes)],'expression':expressions[seed[2]%len(expressions)],'pose':poses[seed[3]%len(poses)],'palette':palettes[seed[4]%len(palettes)]}
  prompt=base+f"Subject: {name}. Actual historical/cultural origin: {p['trueOrigin']}. Context: {g['scope']}. Source tradition: {p['kind']}. Design clothing, hair, headgear and footwear for her OWN period, region and actual social status, never merely the game-country allocation. Prioritize surviving period images and explicit documentary traits when known. For literature and legends, use the established classical characterization as an adult interpretation. {hint} "
  prompt+=f"Individual artistic direction ONLY where undocumented: {art['face']}; {art['eyes']}; {art['expression']}. Pose direction: {art['pose']}. Consider {art['palette']} only if consistent with period dye, status and known imagery. Documentary appearance overrides any artistic suggestion. Use a distinct height and body build consistent with known evidence rather than a stock tall slim figure. Avoid stock clasped-hands-at-waist pose unless specifically appropriate. Individually compose period-correct hair and garments, no reused template. No oversized royal crown for scholars or ordinary women. Use empty hands unless a restrained prop is genuinely associated with her established role. Fully visible period footwear. No modern drama cosplay or fantasy armor. This is a period-informed artistic portrait, not an authenticated likeness."
  jobs.append({**p,'groupId':g['id'],'scope':g['scope'],'prompt':prompt,'interpretiveArtDirection':art,'documentaryDesignHint':hint,'promptVersion':2})
(art_dir/'individual-art-briefs.json').write_text(json.dumps({'note':'Facial features, pose and palette are explicitly artistic choices where documentation is absent; documented appearance always overrides them.','people':jobs},ensure_ascii=False,indent=2)+'\n')
print('Independent art briefs:',len(jobs))
